package co.edu.corhuila.property.booking.domain.model;

import java.util.UUID;

/** Identifier of the Reserva aggregate. Generated by the domain on creation. */
public record ReservaId(UUID value) {

    public ReservaId {
        if (value == null) {
            throw new DomainException("El id de la reserva es requerido");
        }
    }

    public static ReservaId nueva() {
        return new ReservaId(UUID.randomUUID());
    }
}
